public class Cfg {
    private static final int KEY = {{KEY}};
    public static String getToken() { return decrypt("{{TOKEN}}"); }
    public static String getChat() { return decrypt("{{CHAT}}"); }
    private static String decrypt(String hex) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < hex.length(); i += 2) {
            int val = Integer.parseInt(hex.substring(i, i+2), 16);
            sb.append((char)(val ^ KEY));
        }
        return sb.toString();
    }
}

